export const definitions=catalog.map(d=>({...d,...mechanics[d.kind],params:{...mechanics[d.kind].params,...(d.kind==='vip'&&d.region!=='AR'?{localPrivacyLevel:7}:{})}}));

// Public projection belongs to the model, not to UI consumers. Canonical private
// facts remain locally owned for simulation; changing view never leaks them.
export function viewState(state,viewer='小夏'){
 const s=structuredClone(state),d=definitions.find(d=>d.id===s.id);
 if(d.kind==='shield'&&s.hidden&&s.role==='member')s.shieldStock='按当前职位隐藏';
 if(d.kind==='undercover'&&s.phase!=='ended'){s.wordCards={[viewer]:s.wordCards[viewer]||'未分词'};s.roles={[viewer]:s.roles[viewer]||'本地村民'};}
 return s;
}
